package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.Db;
import io.tenvyr.platform.Json;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

public final class RuntimeConnectionService {
    private final Db db;
    private final ConcurrentHashMap<String,CompletableFuture<ObjectNode>> inFlight=new ConcurrentHashMap<>();
    public static final Set<String> KINDS=Set.of("codex","claude","opencode","generic-cli","http-worker","kafka-worker");
    public static final Set<String> CAPABILITIES=Set.of("invocation","structuredResult","progressEvents","heartbeat","cancellation","artifacts","observedDelegation","supervisedDelegation","plannerOutput","verifierDecision","toolActionInterception","localProcessTermination");
    public RuntimeConnectionService(Db db){this.db=db;}
    public ObjectNode createConnection(String id,JsonNode profile){try{return db.transaction(tx->createConnection(tx,id,profile));}catch(Db.Failure e){if("23505".equals(e.sqlState()))throw fail("CONNECTION_ALREADY_EXISTS","Connection already exists");throw e;}}
    public ObjectNode createConnection(Db tx,String id,JsonNode raw){validateId(id);ObjectNode profile=parseConnectionProfile(raw);if(tx.exists("SELECT 1 FROM runtime_connections WHERE \"connectionId\"=?",id))throw fail("CONNECTION_ALREADY_EXISTS","Connection already exists");ObjectNode revision=freeze(id,1,profile);
        tx.insert("runtime_connections",Json.object("connectionId",id,"name",profile.get("name"),"runtimeKind",profile.get("runtimeKind"),"executorId",profile.get("executorId"),"version",profile.get("version"),"currentRevisionNumber",1,"statusState","DRAFT","statusReasonCode","none"));persistRevision(tx,revision);return revision;}
    public ObjectNode reviseConnection(String id,JsonNode profile){return db.transaction(tx->reviseConnection(tx,id,profile));}
    public ObjectNode reviseConnection(Db tx,String id,JsonNode raw){ObjectNode row=lock(tx,id);notRevoked(row);ObjectNode revision=freeze(id,Json.integer(row,"currentRevisionNumber",0)+1,parseConnectionProfile(raw));persistRevision(tx,revision);tx.execute("UPDATE runtime_connections SET \"currentRevisionNumber\"=?,\"statusState\"='DRAFT',\"statusReasonCode\"='none',\"statusTestedAt\"=NULL,\"statusTestedVersion\"=NULL,\"updatedAt\"=now() WHERE \"connectionId\"=?",revision.get("revisionNumber"),id);return revision;}
    public ObjectNode revokeConnection(String id){return db.transaction(tx->revokeConnection(tx,id));}
    public ObjectNode revokeConnection(Db tx,String id){lock(tx,id);tx.execute("UPDATE runtime_connections SET \"statusState\"='REVOKED',\"statusReasonCode\"='revoked',\"updatedAt\"=now() WHERE \"connectionId\"=?",id);return Json.object("state","REVOKED","reasonCode","revoked");}
    public ObjectNode claimRevision(String id){return db.transaction(tx->claimRevision(tx,id));}
    public ObjectNode claimRevision(Db tx,String id){ObjectNode row=lock(tx,id);notRevoked(row);ObjectNode rev=tx.one("SELECT * FROM connection_revisions WHERE \"connectionId\"=? AND \"revisionNumber\"=?",id,row.get("currentRevisionNumber"));if(rev==null)throw fail("CONNECTION_NOT_FOUND","Current revision missing");return parseConnectionRevision(Json.object("schemaVersion","1","connectionId",id,"revisionNumber",rev.get("revisionNumber"),"createdAt",rev.get("createdAt"),"profile",rev.get("profile"),"configHash",rev.get("configHash"),"capabilities",rev.get("capabilities")));}
    public ObjectNode connectionStatus(String id){ObjectNode row=db.one("SELECT * FROM runtime_connections WHERE \"connectionId\"=?",id);if(row==null)throw fail("CONNECTION_NOT_FOUND","Connection missing");return status(row);}
    public List<ObjectNode> listConnections(){return db.query("SELECT * FROM runtime_connections ORDER BY \"createdAt\" ASC").stream().map(row->Json.object("connectionId",row.get("connectionId"),"name",row.get("name"),"runtimeKind",row.get("runtimeKind"),"executorId",row.get("executorId"),"version",row.get("version"),"status",status(row))).toList();}
    public ObjectNode testConnection(String id,Map<String,String> environment){CompletableFuture<ObjectNode> mine=new CompletableFuture<>(),existing=inFlight.putIfAbsent(id,mine);if(existing!=null)return existing.join();try{ObjectNode result=probe(id,environment);mine.complete(result);return result;}catch(RuntimeException e){mine.completeExceptionally(e);throw e;}finally{inFlight.remove(id,mine);}}
    private ObjectNode probe(String id,Map<String,String> environment){ObjectNode revision=claimRevision(id);JsonNode profile=revision.path("profile"),cli=profile.path("cli");if(!cli.isObject())throw fail("CONNECTION_PROBE_UNSUPPORTED","Connection has no fixed CLI probe");ObjectNode current=connectionStatus(id);if(current.hasNonNull("testedAt")&&Instant.now().toEpochMilli()-Instant.parse(current.path("testedAt").asText()).toEpochMilli()<5000)throw fail("CONNECTION_TEST_RATE_LIMITED","Connection was tested less than 5000ms ago");Instant tested=Instant.now();ObjectNode result=runProbe(cli,cli.path("probe"),environment);if(Json.bool(result,"ok",false)&&cli.has("authProbe")){ObjectNode auth=runProbe(cli,cli.path("authProbe"),environment);if(!Json.bool(auth,"ok",false))result=auth;}
        boolean degraded=Json.bool(result,"ok",false)&&profile.hasNonNull("version")&&result.hasNonNull("version")&&!profile.get("version").equals(result.get("version"));String reason=degraded?"unsupported-version":Json.text(result,"reasonCode"),state=degraded?"DEGRADED":Json.bool(result,"ok",false)?"AVAILABLE":reason.equals("auth-required")?"AUTH_REQUIRED":"UNAVAILABLE";ObjectNode receipt=Json.object("connectionId",id,"revisionNumber",revision.get("revisionNumber"),"testedAt",tested.toString(),"state",state,"reasonCode",reason,"durationMs",result.get("durationMs"));if(result.hasNonNull("version"))receipt.set("testedVersion",result.get("version"));
        JsonNode testedVersion=result.get("version");boolean persisted=db.transaction(tx->{ObjectNode row=lock(tx,id);notRevoked(row);if(!row.get("currentRevisionNumber").equals(revision.get("revisionNumber")))return false;tx.execute("UPDATE runtime_connections SET \"statusState\"=?,\"statusReasonCode\"=?,\"statusTestedAt\"=?,\"statusTestedVersion\"=?,\"updatedAt\"=now() WHERE \"connectionId\"=?",state,reason,tested,testedVersion,id);return true;});if(!persisted)receipt.put("superseded",true);return receipt;}
    public static ObjectNode runProbe(JsonNode cli,JsonNode probe,Map<String,String> host){ProcessBoundary.Result result=ProcessBoundary.run(Json.text(cli,"command"),ProcessBoundary.args(probe.path("args")),cli.hasNonNull("cwd")?Path.of(cli.path("cwd").asText()):null,ProcessBoundary.environment(cli,host,false),Json.longValue(probe,"wallTimeMs",10000),Json.integer(probe,"maxOutputBytes",65536));String reason=result.timedOut()?"timeout":result.exceeded()?"malformed-output":result.status()==null||result.status()==-1?"missing-executable":result.status()!=0?"command-failed":"none";if(result.status()!=null&&result.status()!=0&&!result.timedOut()&&!result.exceeded()&&(Json.bool(probe,"authAnyNonZero",false)||containsCode(probe.path("authExitCodes"),result.status())))reason="auth-required";ObjectNode outcome=Json.object("ok",reason.equals("none"),"reasonCode",reason,"durationMs",result.durationMs());if(reason.equals("none")&&Json.bool(probe,"expectsVersion",false)){String version=result.stdout().lines().findFirst().orElse("").trim();if(version.length()>128||!version.matches("[A-Za-z0-9._+\\-]+")){outcome.put("ok",false);outcome.put("reasonCode","malformed-output");}else outcome.put("version",version);}return outcome;}
    private static boolean containsCode(JsonNode codes,int code){for(JsonNode n:codes)if(n.asInt()==code)return true;return false;}
    private static ObjectNode lock(Db tx,String id){ObjectNode row=tx.one("SELECT * FROM runtime_connections WHERE \"connectionId\"=? FOR UPDATE",id);if(row==null)throw fail("CONNECTION_NOT_FOUND","Connection missing");return row;}
    private static void notRevoked(JsonNode row){if(Json.text(row,"statusState").equals("REVOKED"))throw fail("CONNECTION_REVOKED","Connection revoked");}
    private static ObjectNode status(JsonNode row){ObjectNode out=Json.object("state",row.get("statusState"),"reasonCode",row.get("statusReasonCode"));if(row.hasNonNull("statusTestedAt"))out.set("testedAt",row.get("statusTestedAt"));if(row.hasNonNull("statusTestedVersion"))out.set("testedVersion",row.get("statusTestedVersion"));return out;}
    private static void persistRevision(Db tx,JsonNode r){tx.insert("connection_revisions",Json.object("connectionId",r.get("connectionId"),"revisionNumber",r.get("revisionNumber"),"createdAt",r.get("createdAt"),"profile",r.get("profile"),"configHash",r.get("configHash"),"capabilities",r.get("capabilities")));}
    public static ObjectNode freeze(String id,int number,JsonNode raw){validateId(id);if(number<1)throw invalid("revisionNumber");ObjectNode profile=parseConnectionProfile(raw);ObjectNode capabilities=Json.object();profile.path("declaredCapabilities").fields().forEachRemaining(e->{if(Json.bool(e.getValue(),"supported",false))capabilities.set(e.getKey(),e.getValue().deepCopy());});return Json.object("schemaVersion","1","connectionId",id,"revisionNumber",number,"createdAt",Instant.now().toString(),"profile",profile,"configHash",Json.hash(profile),"capabilities",capabilities);}
    public static ObjectNode buildConnectionReference(JsonNode revision){ObjectNode r=parseConnectionRevision(revision),out=Json.object("schemaVersion","1","connectionId",r.get("connectionId"),"revisionNumber",r.get("revisionNumber"),"runtimeKind",r.path("profile").get("runtimeKind"),"configHash",r.get("configHash"),"capabilities",r.get("capabilities"));if(r.path("profile").has("version"))out.set("version",r.path("profile").get("version"));return out;}
    public static ObjectNode parseConnectionReference(JsonNode raw){ObjectNode n=object(raw,"reference",Set.of("schemaVersion","connectionId","revisionNumber","runtimeKind","version","configHash","capabilities"));if(!Json.text(n,"schemaVersion").equals("1")||!KINDS.contains(Json.text(n,"runtimeKind"))||!Json.text(n,"configHash").matches("[0-9a-f]{64}"))throw invalid("reference identity");validateId(Json.text(n,"connectionId"));positive(n,"revisionNumber",Integer.MAX_VALUE);capabilities(n.path("capabilities"));if(n.has("version"))version(n.get("version"));return n;}
    public static ObjectNode parseConnectionRevision(JsonNode raw){ObjectNode n=object(raw,"revision",Set.of("schemaVersion","connectionId","revisionNumber","createdAt","profile","configHash","capabilities"));if(!Json.text(n,"schemaVersion").equals("1"))throw invalid("schemaVersion");validateId(Json.text(n,"connectionId"));positive(n,"revisionNumber",Integer.MAX_VALUE);try{Instant.parse(bounded(n.get("createdAt"),"createdAt",40));}catch(Exception e){throw invalid("createdAt");}ObjectNode profile=parseConnectionProfile(n.get("profile"));if(!Json.hash(profile).equals(Json.text(n,"configHash")))throw invalid("configHash mismatch");capabilities(n.path("capabilities"));ObjectNode expected=Json.object();profile.path("declaredCapabilities").fields().forEachRemaining(e->{if(Json.bool(e.getValue(),"supported",false))expected.set(e.getKey(),e.getValue());});if(!expected.equals(n.path("capabilities")))throw invalid("capabilities mismatch");return n;}
    public static ObjectNode parseConnectionProfile(JsonNode raw){ObjectNode n=object(raw,"profile",Set.of("name","runtimeKind","executorId","version","credentialRefs","declaredCapabilities","cli"));bounded(n.get("name"),"name",255);bounded(n.get("executorId"),"executorId",255);String kind=Json.text(n,"runtimeKind");if(!KINDS.contains(kind))throw invalid("runtimeKind");if(n.has("version"))version(n.get("version"));JsonNode refs=n.path("credentialRefs");if(!refs.isArray()||refs.size()>16)throw invalid("credentialRefs");for(JsonNode ref:refs){object(ref,"credentialRef",Set.of("kind","name"));if(!Json.text(ref,"kind").equals("env"))throw invalid("credential kind");envName(ref.get("name"));}capabilities(n.path("declaredCapabilities"));if(n.has("cli")){if(kind.endsWith("worker"))throw invalid("worker CLI");parseCli(n.get("cli"));}else if(kind.equals("generic-cli"))throw invalid("missing CLI");return n;}
    static ObjectNode parseCli(JsonNode raw){ObjectNode n=object(raw,"cli",Set.of("command","args","modelArgvPrefix","cwd","envAllowlist","secrets","probe","authProbe"));absolute(n.get("command"),"command");args(n.get("args"));if(n.has("modelArgvPrefix"))args(n.get("modelArgvPrefix"));if(n.has("cwd"))absolute(n.get("cwd"),"cwd");for(String key:List.of("envAllowlist","secrets"))if(n.has(key))envRefs(n.get(key));parseProbe(n.get("probe"));if(n.has("authProbe"))parseProbe(n.get("authProbe"));return n;}
    static void parseProbe(JsonNode raw){ObjectNode n=object(raw,"probe",Set.of("args","wallTimeMs","maxOutputBytes","authExitCodes","authAnyNonZero","expectsVersion"));args(n.get("args"));if(n.has("wallTimeMs"))positive(n,"wallTimeMs",60000);if(n.has("maxOutputBytes"))positive(n,"maxOutputBytes",1048576);if(n.has("authExitCodes")){JsonNode codes=n.get("authExitCodes");if(!codes.isArray()||codes.isEmpty()||codes.size()>8)throw invalid("authExitCodes");for(JsonNode code:codes)if(!code.isIntegralNumber()||code.asInt()<1||code.asInt()>255)throw invalid("authExitCode");}for(String key:List.of("authAnyNonZero","expectsVersion"))if(n.has(key)&&!n.get(key).isBoolean())throw invalid(key);}
    static void capabilities(JsonNode raw){if(raw==null||!raw.isObject())throw invalid("capabilities");raw.fields().forEachRemaining(e->{if(!CAPABILITIES.contains(e.getKey()))throw invalid("capability");ObjectNode cap=object(e.getValue(),"capability",Set.of("supported","source","version"));if(!cap.path("supported").isBoolean()||!Set.of("configured","detected","verified").contains(Json.text(cap,"source")))throw invalid("capability claim");if(cap.has("version"))version(cap.get("version"));});}
    static ObjectNode object(JsonNode raw,String field,Set<String> allowed){if(raw==null||!raw.isObject())throw invalid(field);for(String key:Json.keys(raw))if(!allowed.contains(key))throw invalid(field+" unknown field "+key);return (ObjectNode)raw.deepCopy();}
    static String bounded(JsonNode raw,String field,int max){if(raw==null||!raw.isTextual()||raw.asText().isBlank()||raw.asText().length()>max||raw.asText().indexOf(0)>=0)throw invalid(field);return raw.asText();}
    static void absolute(JsonNode n,String field){if(!Path.of(bounded(n,field,4096)).isAbsolute())throw invalid(field+" must be absolute");}
    static void args(JsonNode args){if(args==null||!args.isArray()||args.size()>64)throw invalid("args");for(JsonNode arg:args)bounded(arg,"arg",1024);}
    static void envRefs(JsonNode raw){if(raw==null||!raw.isObject()||raw.size()>64)throw invalid("env refs");raw.fields().forEachRemaining(e->{envName(Json.value(e.getKey()));envName(e.getValue());});}
    static void envName(JsonNode raw){if(!bounded(raw,"env name",255).matches("[A-Za-z0-9_]+"))throw invalid("env name");}
    static void version(JsonNode raw){if(!bounded(raw,"version",128).matches("[A-Za-z0-9._+\\-]+"))throw invalid("version");}
    static void validateId(String id){if(id==null||id.length()>255||!id.matches("[A-Za-z0-9_.:\\-]+"))throw invalid("connectionId");}
    static void positive(JsonNode n,String field,int max){JsonNode v=n.get(field);if(v==null||!v.isIntegralNumber()||v.asLong()<1||v.asLong()>max)throw invalid(field);}
    static RuntimeFailure invalid(String message){return fail("CONNECTION_PROFILE_INVALID",message);}
    static RuntimeFailure fail(String code,String message){return new RuntimeFailure(code,message);}
}
